function evaluate(node, env) {
  switch (node.kind) {
    case 'num': return node.value;                          // 숫자는 그 값
    case 'var': return env[node.name];                      // 이름은 환경에서(3장)
    case 'bin': {
      const a = evaluate(node.left, env);                   // 왼쪽 재귀
      const b = evaluate(node.right, env);                  // 오른쪽 재귀
      return node.op === '+' ? a + b : node.op === '-' ? a - b
           : node.op === '*' ? a * b : a / b;               // 연산 적용
    }
  }
}
// (+ 2 (* 3 4)) → 곱셈부터(더 깊이) → 3*4=12 → 2+12=14

